import type { Metadata } from "next";
import Link from "next/link";
import { redirect } from "next/navigation";
import { Suspense } from "react";

import { buttonVariants } from "@/components/ui/button";
import { exigirUsuario } from "@/features/auth/sessao";
import { PerguntaComoFoi } from "@/features/como-foi/components/pergunta-como-foi";
import { obterComoFoi } from "@/features/como-foi/consultas";
import { EsqueletoSecoes } from "@/features/dashboard/components/esqueleto-secoes";
import { SecoesRecomendadas } from "@/features/dashboard/components/secoes-recomendadas";
import { lerRodada } from "@/features/dashboard/rodada";
import { idsNasListas } from "@/features/listas/consultas";
import { BotaoNoite } from "@/features/noite/components/botao-noite";
import { obterPreferencias } from "@/features/preferencias/consultas";
import { resumirPreferencias } from "@/features/preferencias/resumo";
import { obterReacoes } from "@/features/reacoes/consultas";
import {
  EsqueletoSurpresa,
  SurpresaDashboard,
} from "@/features/surpresa/components/surpresa-dashboard";

export const metadata: Metadata = { title: "Início" };

export default async function DashboardPage({ searchParams }: PageProps<"/dashboard">) {
  const usuario = await exigirUsuario();
  const preferencias = await obterPreferencias();
  if (!preferencias) redirect("/onboarding");

  const rodada = lerRodada((await searchParams).rodada);
  const [reacoes, excluir, comoFoi] = await Promise.all([
    obterReacoes(),
    idsNasListas(),
    obterComoFoi(),
  ]);
  const urlAtual = rodada ? `/dashboard?rodada=${rodada}` : "/dashboard";
  const proximaRodada = `/dashboard?rodada=${rodada + 1}`;

  return (
    <div className="mx-auto flex w-full max-w-6xl flex-1 flex-col gap-10 px-4 py-10">
      <header className="flex flex-wrap items-end justify-between gap-4">
        <div className="flex flex-col gap-2">
          <h1 className="text-4xl tracking-tight sm:text-5xl">Olá, {usuario.nome}</h1>
          <p className="text-muted-foreground" data-testid="resumo-preferencias">
            {resumirPreferencias(preferencias)}
          </p>
        </div>
        <div className="flex w-full flex-col gap-3 sm:w-auto sm:flex-row sm:items-start">
          <BotaoNoite />
          <Link href={proximaRodada} className={buttonVariants({ variant: "outline", size: "lg" })}>
            Gerar outras recomendações
          </Link>
        </div>
      </header>

      {/* A chave troca o cartão quando outra escolha passa a ser a mais recente. */}
      {comoFoi && <PerguntaComoFoi key={comoFoi.id} pergunta={comoFoi} />}

      {/* A chave por rodada mostra o esqueleto de novo a cada "Gerar outras recomendações". */}
      <Suspense key={rodada} fallback={<EsqueletoSecoes />}>
        <SecoesRecomendadas
          entrada={{
            preferencias,
            usuarioId: usuario.id,
            data: new Date(),
            rodada,
            reacoes,
            excluir,
          }}
          urlAtual={urlAtual}
          proximaRodada={proximaRodada}
          meio={
            <Suspense fallback={<EsqueletoSurpresa />}>
              <SurpresaDashboard
                preferencias={preferencias}
                excluir={[...excluir, ...reacoes.map((reacao) => reacao.tmdbId)]}
              />
            </Suspense>
          }
        />
      </Suspense>
    </div>
  );
}
import type { Metadata } from "next";
import { notFound } from "next/navigation";

import { Cabecalho } from "@/features/filme/components/cabecalho-filme";
import { Elenco } from "@/features/filme/components/elenco";
import { OndeAssistir } from "@/features/filme/components/onde-assistir";
import { AcoesTitulo, Secao, Sinopse, Voltar } from "@/features/filme/components/pagina-titulo";
import { Trailer } from "@/features/filme/components/trailer";
import { tituloComAno } from "@/features/filme/formatar";
import { buscaPorId } from "@/features/filme/ler-id";
import { obterStatusLista } from "@/features/listas/consultas";
import { obterReacao } from "@/features/reacoes/consultas";
import { Temporadas } from "@/features/serie/components/temporadas";
import { dadosDaSerie } from "@/features/serie/formatar";
import type { Midia } from "@/lib/midia";
import { obterSerie } from "@/lib/tmdb/series";

const buscarSerie = buscaPorId(obterSerie);

export async function generateMetadata({ params }: PageProps<"/serie/[id]">): Promise<Metadata> {
  const serie = await buscarSerie((await params).id);
  return { title: serie ? tituloComAno(serie) : "Série não encontrada" };
}

export default async function SeriePage({ params }: PageProps<"/serie/[id]">) {
  const serie = await buscarSerie((await params).id);
  if (!serie) notFound();
  const midia: Midia = { tipo: "serie", tmdbId: serie.id };
  const [reacao, statusLista] = await Promise.all([obterReacao(midia), obterStatusLista(midia)]);

  return (
    <div className="mx-auto flex w-full max-w-6xl flex-1 flex-col gap-10 px-4 py-8">
      <Voltar />

      <Cabecalho
        titulo={serie}
        dados={dadosDaSerie(serie)}
        acoes={<AcoesTitulo midia={midia} reacao={reacao} statusLista={statusLista} />}
      />

      <Sinopse texto={serie.sinopse} rotulo="Criação" nomes={serie.criacao} />

      {/* Sem `origem`: a origem "serie" do trailer_aberto fica para depois (spec series-pagina). */}
      {serie.trailerYoutube && (
        <Secao titulo="Trailer">
          <Trailer chave={serie.trailerYoutube} titulo={serie.titulo} />
        </Secao>
      )}

      {serie.temporadas.length > 0 && (
        <Secao titulo="Temporadas">
          <Temporadas temporadas={serie.temporadas} />
        </Secao>
      )}

      <Secao titulo="Onde assistir no Brasil">
        <OndeAssistir dados={serie.ondeAssistir} tipo="serie" />
      </Secao>

      {serie.elenco.length > 0 && (
        <Secao titulo="Elenco">
          <Elenco pessoas={serie.elenco} />
        </Secao>
      )}
    </div>
  );
}
import Image from "next/image";

import { contar } from "@/features/serie/formatar";
import { urlImagem } from "@/lib/tmdb/imagens";
import type { Temporada } from "@/lib/tmdb/tipos";

/** Uma linha por temporada: pôster pequeno (sem ele, o número), nome, ano e episódios. */
export function Temporadas({ temporadas }: { temporadas: Temporada[] }) {
  return (
    <ul className="divide-border/60 flex max-w-3xl flex-col divide-y">
      {temporadas.map((temporada) => {
        const poster = urlImagem(temporada.posterPath, "w92");
        const detalhes = [temporada.ano, contar(temporada.episodios, "episódio", "episódios")]
          .filter(Boolean)
          .join(" · ");
        return (
          <li key={temporada.numero} className="flex items-center gap-4 py-3">
            <div className="bg-muted relative aspect-[2/3] w-12 shrink-0 overflow-hidden rounded-md">
              {poster ? (
                <Image src={poster} alt="" fill sizes="48px" className="object-cover" />
              ) : (
                <span
                  aria-hidden="true"
                  className="text-muted-foreground flex h-full items-center justify-center text-sm font-semibold"
                >
                  {temporada.numero}
                </span>
              )}
            </div>
            <div>
              <p className="font-medium">{temporada.nome}</p>
              <p className="text-muted-foreground text-sm">{detalhes}</p>
            </div>
          </li>
        );
      })}
    </ul>
  );
}
import "server-only";

import { clienteTmdbPadrao, type ClienteTmdb, type Parametros } from "@/lib/tmdb/cliente";
import {
  anoDe,
  elencoDe,
  nuloSe404,
  ondeAssistirDe,
  paraGeneros,
  paraPagina,
  parametrosDescoberta,
  trailerDe,
  validar,
} from "@/lib/tmdb/comum";
import {
  detalhesSerieTmdb,
  generosTmdb,
  serieTmdb,
  type DetalhesSerieTmdb,
  type SerieTmdb,
} from "@/lib/tmdb/esquemas";
import type {
  ClassificacaoBR,
  FiltrosDescobertaSerie,
  OrdemDescoberta,
  Pagina,
  SerieDetalhes,
  SerieResumo,
} from "@/lib/tmdb/tipos";

const HORA = 3600;
const CACHE_LISTAS = 6 * HORA;
const CACHE_SERIE = 24 * HORA;

const ORDENS: Record<OrdemDescoberta, string> = {
  popularidade: "popularity.desc",
  nota: "vote_average.desc",
  lancamento: "first_air_date.desc",
};

/** Classificações do Brasil, da mais leve à mais restrita. */
export const CLASSIFICACOES_BR: readonly ClassificacaoBR[] = ["L", "10", "12", "14", "16", "18"];

function paraResumo(serie: SerieTmdb): SerieResumo {
  return {
    id: serie.id,
    titulo: serie.name,
    tituloOriginal: serie.original_name,
    sinopse: serie.overview,
    posterPath: serie.poster_path,
    backdropPath: serie.backdrop_path,
    generos: serie.genre_ids,
    ano: anoDe(serie.first_air_date),
    nota: serie.vote_average,
    votos: serie.vote_count,
    popularidade: serie.popularity,
  };
}

/** Média de `episode_run_time`; sem ela, a duração do último episódio exibido. */
function duracaoEpisodio(serie: DetalhesSerieTmdb): number | null {
  const duracoes = serie.episode_run_time.filter((minutos) => minutos > 0);
  if (duracoes.length === 0) return serie.last_episode_to_air?.runtime || null;
  return Math.round(duracoes.reduce((soma, minutos) => soma + minutos, 0) / duracoes.length);
}

function classificacaoDe(serie: DetalhesSerieTmdb): ClassificacaoBR | null {
  const doBrasil = serie.content_ratings.results.find((r) => r.iso_3166_1 === "BR")?.rating;
  return CLASSIFICACOES_BR.find((classificacao) => classificacao === doBrasil) ?? null;
}

function paraDetalhes(serie: DetalhesSerieTmdb): SerieDetalhes {
  return {
    ...paraResumo({ ...serie, genre_ids: [] }),
    generos: paraGeneros(serie.genres),
    duracaoEpisodioMin: duracaoEpisodio(serie),
    temporadas: serie.seasons
      .filter((temporada) => temporada.season_number > 0)
      .sort((a, b) => a.season_number - b.season_number)
      .map((temporada) => ({
        numero: temporada.season_number,
        nome: temporada.name,
        episodios: temporada.episode_count,
        ano: anoDe(temporada.air_date),
        posterPath: temporada.poster_path,
      })),
    slogan: serie.tagline,
    trailerYoutube: trailerDe(serie.videos.results),
    elenco: elencoDe(serie.credits),
    criacao: serie.created_by.map((pessoa) => pessoa.name),
    classificacao: classificacaoDe(serie),
    ondeAssistir: ondeAssistirDe(serie["watch/providers"]),
  };
}

/** Funções de séries sobre um cliente qualquer; os testes passam um cliente com `fetch` falso. */
export function criarApiSeries(cliente: ClienteTmdb) {
  return {
    async descobrirSeries(filtros: FiltrosDescobertaSerie = {}): Promise<Pagina<SerieResumo>> {
      const parametros: Parametros = {
        ...parametrosDescoberta(filtros, ORDENS),
        first_air_date_year: filtros.ano,
        "first_air_date.lte": filtros.lancadoAte,
      };
      const dados = await cliente.requisitar("/discover/tv", parametros, CACHE_LISTAS);
      return paraPagina(serieTmdb, dados, paraResumo);
    },

    obterSerie(id: number): Promise<SerieDetalhes | null> {
      return nuloSe404(async () => {
        const dados = await cliente.requisitar(
          `/tv/${id}`,
          { append_to_response: "videos,credits,watch/providers,content_ratings" },
          CACHE_SERIE,
        );
        return paraDetalhes(validar(detalhesSerieTmdb, dados));
      });
    },

    /** Gêneros de TV: outra lista que a dos filmes, com IDs próprios. */
    async generosSeries(): Promise<{ id: number; nome: string }[]> {
      const dados = await cliente.requisitar("/genre/tv/list", {}, CACHE_SERIE);
      return paraGeneros(validar(generosTmdb, dados).genres);
    },
  };
}

export type ApiSeries = ReturnType<typeof criarApiSeries>;

let padrao: ApiSeries | undefined;
const api = () => (padrao ??= criarApiSeries(clienteTmdbPadrao()));

export const descobrirSeries: ApiSeries["descobrirSeries"] = (...args) =>
  api().descobrirSeries(...args);
export const obterSerie: ApiSeries["obterSerie"] = (...args) => api().obterSerie(...args);
export const generosSeries: ApiSeries["generosSeries"] = () => api().generosSeries();

